/* Ertha Battle Calculator - generated by ertha-wiki pipeline, do not edit by hand.
   Troop stats and wall bonuses are synced from the live game data.       */
$(function () {
  var host = document.getElementById('ertha-battle-calc');
  if (!host) return;

  var TROOPS = [{"name": "Scraprunner", "cls": "Infantry", "role": "Warrior", "off": 40, "di": 20, "dh": 10, "da": 2, "carry": 25}, {"name": "Wastelander", "cls": "Infantry", "role": "Warrior", "off": 25, "di": 35, "dh": 30, "da": 3, "carry": 30}, {"name": "Pounder", "cls": "Heavy", "role": "Warrior", "off": 120, "di": 50, "dh": 30, "da": 5, "carry": 100}, {"name": "Berserker", "cls": "Heavy", "role": "Warrior", "off": 105, "di": 80, "dh": 100, "da": 10, "carry": 120}, {"name": "Stormhawk", "cls": "Air", "role": "Warrior", "off": 200, "di": 140, "dh": 50, "da": 30, "carry": 0}, {"name": "Blacktalon", "cls": "Air", "role": "Warrior", "off": 260, "di": 160, "dh": 110, "da": 40, "carry": 0}, {"name": "Sentinel", "cls": "Infantry", "role": "Defender", "off": 20, "di": 40, "dh": 30, "da": 3, "carry": 15}, {"name": "Warden", "cls": "Infantry", "role": "Defender", "off": 5, "di": 50, "dh": 40, "da": 5, "carry": 35}, {"name": "Pulsar", "cls": "Heavy", "role": "Defender", "off": 40, "di": 110, "dh": 50, "da": 15, "carry": 100}, {"name": "Hullbreaker", "cls": "Heavy", "role": "Defender", "off": 70, "di": 90, "dh": 110, "da": 25, "carry": 65}, {"name": "Cloudshield", "cls": "Air", "role": "Defender", "off": 110, "di": 200, "dh": 210, "da": 100, "carry": 0}, {"name": "Thunderwing", "cls": "Air", "role": "Defender", "off": 150, "di": 220, "dh": 150, "da": 330, "carry": 0}, {"name": "Lancer", "cls": "Infantry", "role": "Mediator", "off": 30, "di": 30, "dh": 20, "da": 10, "carry": 25}, {"name": "Neoblade", "cls": "Infantry", "role": "Mediator", "off": 40, "di": 25, "dh": 20, "da": 5, "carry": 30}, {"name": "Centurion", "cls": "Heavy", "role": "Mediator", "off": 75, "di": 75, "dh": 40, "da": 20, "carry": 50}, {"name": "Vanguard", "cls": "Heavy", "role": "Mediator", "off": 90, "di": 90, "dh": 90, "da": 25, "carry": 130}, {"name": "Skyshard", "cls": "Air", "role": "Mediator", "off": 130, "di": 240, "dh": 150, "da": 200, "carry": 0}, {"name": "Stratos", "cls": "Air", "role": "Mediator", "off": 210, "di": 300, "dh": 200, "da": 250, "carry": 0}];
  var WALL = [10, 12, 13, 14, 15, 17, 19, 21, 23, 26, 29, 32, 35, 38, 41, 45, 49, 53, 58, 63]; /* index = City Wall level, value = defense bonus in % */
  var byName = {};
  TROOPS.forEach(function (t) { byName[t.name] = t; });

  function el(tag, attrs, parent) {
    var e = document.createElement(tag);
    for (var k in attrs) {
      if (k === 'text') e.textContent = attrs[k];
      else if (k === 'html') e.innerHTML = attrs[k];
      else e.setAttribute(k, attrs[k]);
    }
    if (parent) parent.appendChild(e);
    return e;
  }

  function troopSelect(parent) {
    var s = el('select', {}, parent);
    el('option', { value: '', text: '- troop -' }, s);
    TROOPS.forEach(function (t) {
      el('option', { value: t.name, text: t.name + ' (' + t.cls + ', ' + t.role + ')' }, s);
    });
    return s;
  }

  var css = '#ertha-battle-calc table{border-collapse:collapse}' +
    '#ertha-battle-calc td,#ertha-battle-calc th{padding:3px 6px}' +
    '#ertha-battle-calc input[type=number]{width:70px}' +
    '#ertha-battle-calc .ebc-side{display:inline-block;vertical-align:top;margin:0 18px 12px 0}' +
    '#ertha-battle-calc .ebc-result{margin-top:10px;padding:10px;border:1px solid #888;border-radius:4px}' +
    '#ertha-battle-calc .ebc-win{font-weight:bold;font-size:120%}' +
    '#ertha-battle-calc button{padding:6px 16px;font-weight:bold;cursor:pointer}';
  el('style', { text: css }, host);

  var ROWS = 5;
  function buildSide(title) {
    var box = el('div', { 'class': 'ebc-side' }, host);
    el('h3', { text: title }, box);
    var tbl = el('table', {}, box);
    var hr = el('tr', {}, tbl);
    el('th', { text: 'Troop' }, hr);
    el('th', { text: 'Qty' }, hr);
    var rows = [];
    for (var i = 0; i < ROWS; i++) {
      var tr = el('tr', {}, tbl);
      var sel = troopSelect(el('td', {}, tr));
      var qty = el('input', { type: 'number', min: '0', value: '' }, el('td', {}, tr));
      rows.push({ sel: sel, qty: qty });
    }
    return { box: box, rows: rows };
  }

  var att = buildSide('Attacker');
  var def = buildSide('Defender');

  var wallP = el('p', {}, def.box);
  el('span', { text: 'Defender City Wall level: ' }, wallP);
  var wallSel = el('select', {}, wallP);
  el('option', { value: '0', text: 'No wall (0%)' }, wallSel);
  WALL.forEach(function (b, i) {
    el('option', { value: String(b), text: 'Level ' + (i + 1) + ' (+' + b + '%)' }, wallSel);
  });

  var modeP = el('p', {}, host);
  el('span', { text: 'Battle mode: ' }, modeP);
  var modeSel = el('select', {}, modeP);
  el('option', { value: 'raid', text: 'Raid (steal resources)' }, modeSel);
  el('option', { value: 'normal', text: 'Normal attack' }, modeSel);

  var btn = el('button', { text: 'Calculate battle' }, host);
  var out = el('div', { 'class': 'ebc-result', style: 'display:none' }, host);

  function readSide(side) {
    var units = [];
    side.rows.forEach(function (r) {
      var t = byName[r.sel.value];
      var q = parseInt(r.qty.value, 10) || 0;
      if (t && q > 0) units.push({ t: t, q: q });
    });
    return units;
  }

  btn.onclick = function () {
    var A = readSide(att), D = readSide(def);
    if (!A.length || !D.length) {
      out.style.display = 'block';
      out.innerHTML = '<i>Add at least one troop with a quantity on each side.</i>';
      return;
    }
    /* attacker composition by quantity */
    var qInf = 0, qHeavy = 0, qAir = 0, totalQ = 0, totalAtt = 0;
    A.forEach(function (u) {
      totalAtt += u.q * u.t.off;
      totalQ += u.q;
      if (u.t.cls === 'Infantry') qInf += u.q;
      else if (u.t.cls === 'Heavy') qHeavy += u.q;
      else qAir += u.q;
    });
    var pInf = totalQ ? qInf / totalQ : 0, pHeavy = totalQ ? qHeavy / totalQ : 0, pAir = totalQ ? qAir / totalQ : 0;

    var totalDef = 0;
    D.forEach(function (u) {
      totalDef += u.q * (u.t.di * pInf + u.t.dh * pHeavy + u.t.da * pAir);
    });
    var wall = parseFloat(wallSel.value) / 100;
    var effDef = totalDef * (1 + wall);

    var attackerWins = totalAtt >= effDef;
    var r = attackerWins ? (totalAtt === 0 ? 0 : effDef / totalAtt) : totalAtt / effDef;
    var raid = modeSel.value === 'raid';
    var winLoss = raid ? Math.pow(r, 1.5) / (1 + Math.pow(r, 1.5)) : Math.min(1, Math.pow(r, 1.5));
    var loseLoss = raid ? 1 - winLoss : 1;
    var attLoss = attackerWins ? winLoss : loseLoss;
    var defLoss = attackerWins ? loseLoss : winLoss;

    function lossTable(units, pct) {
      var h = '<table class="wikitable"><tr><th>Troop</th><th>Start</th><th>Lost</th><th>Survive</th></tr>';
      units.forEach(function (u) {
        var lost = Math.round(u.q * pct);
        h += '<tr><td>' + u.t.name + '</td><td>' + u.q + '</td><td>' + lost + '</td><td>' + (u.q - lost) + '</td></tr>';
      });
      return h + '</table>';
    }
    var loot = 0;
    A.forEach(function (u) {
      var lost = Math.round(u.q * attLoss);
      loot += (u.q - lost) * u.t.carry;
    });

    var html = '<div class="ebc-win">' + (attackerWins ? 'ATTACKER WINS' : 'DEFENDER WINS') + '</div>' +
      '<p>Total attack: <b>' + Math.round(totalAtt).toLocaleString() + '</b> | Effective defense: <b>' +
      Math.round(effDef).toLocaleString() + '</b> (wall +' + wallSel.value + '%)<br>' +
      'Power ratio (loser/winner): <b>' + r.toFixed(3) + '</b> | Mode: <b>' + (raid ? 'Raid' : 'Normal') + '</b></p>' +
      '<p><b>Attacker losses: ' + (attLoss * 100).toFixed(1) + '%</b></p>' + lossTable(A, attLoss) +
      '<p><b>Defender losses: ' + (defLoss * 100).toFixed(1) + '%</b></p>' + lossTable(D, defLoss);
    if (attackerWins) {
      html += '<p><b>Loot capacity of surviving attackers: ' + loot.toLocaleString() +
        '</b> resources (actual loot is capped by the defender\u2019s unprotected storage; the Bunker\u2019s share can never be taken).</p>';
    } else {
      html += '<p>No loot: the attack failed.</p>';
    }
    out.style.display = 'block';
    out.innerHTML = html;
  };
});